import { useCallback, useEffect, useRef, useState } from 'react'
import { AlertsButton } from '@/components/AlertsButton'
import { DecisionCard, type Offer } from '@/components/DecisionCard'
import { EvidenceDrawer, type DrawerView } from '@/components/EvidenceDrawer'
import { Rail } from '@/components/Rail'
import { Routines } from '@/components/Routines'
import { StatusStrip } from '@/components/StatusStrip'
import { SupplyMap, type MapSelection } from '@/components/SupplyMap'
import { COLORS, fetchState, type Card, type State } from '@/lib/api'

const POLL_MS = 5000

export default function App() {
  const [state, setState] = useState<State | null>(null)
  const [error, setError] = useState(false)
  const [nowMs, setNowMs] = useState(Date.now())
  const [selection, setSelection] = useState<MapSelection>({})
  const [hoverRoutes, setHoverRoutes] = useState<string[]>([])
  const [drawer, setDrawer] = useState<DrawerView>(null)
  const [offer, setOffer] = useState<Offer | null>(null)
  const [toast, setToast] = useState<string | null>(null)
  const [pulseNode, setPulseNode] = useState<string | null>(null)
  const [fresh, setFresh] = useState<Set<string>>(new Set())
  const seenEvents = useRef<Set<string> | null>(null)
  const seenCards = useRef<Set<string> | null>(null)
  // A card that was just decided (button or voice): offer to automate the next one like it.
  const lastStatus = useRef<Map<string, string> | null>(null)
  const [justDecided, setJustDecided] = useState<Card | null>(null)
  const [automate, setAutomate] = useState<{ cardId: string; k: number } | null>(null)
  const offset = useRef(0)
  const [path, setPath] = useState(window.location.pathname)
  // Opened from a push alert (/d/<id>?talk=1): show the card as an incoming call.
  const [ringing, setRinging] = useState(new URLSearchParams(window.location.search).get('talk') === '1')
  const stopRinging = () => {
    setRinging(false)
    window.history.replaceState(null, '', window.location.pathname)
  }

  const load = useCallback(async () => {
    try {
      const s = await fetchState()
      offset.current = new Date(s.now).getTime() - Date.now()
      setNowMs(Date.now() + offset.current)
      setState(s)
      setError(false)

      // A new portal drop: pulse its place on the map and say the agents are reading it.
      const ev = new Set(s.events.map((e) => e.id))
      if (seenEvents.current) {
        const added = s.events.filter((e) => !seenEvents.current!.has(e.id))
        if (added.length) {
          const e = added[0]
          const name = (e.path || e.file || '').split('/').pop()
          setToast(`New: ${name}. Agent reading…`)
          setPulseNode(e.node ?? null)
          window.setTimeout(() => setToast(null), 5000)
          window.setTimeout(() => setPulseNode(null), 4500)
        }
      }
      seenEvents.current = ev

      const ids = new Set(s.cards.filter((c) => c.status === 'open').map((c) => c.id))
      if (seenCards.current) {
        const added = [...ids].filter((id) => !seenCards.current!.has(id))
        if (added.length) {
          setFresh((f) => new Set([...f, ...added]))
          window.setTimeout(() => setFresh((f) => new Set([...f].filter((x) => !added.includes(x)))), 2500)
        }
      }
      seenCards.current = ids

      const prev = lastStatus.current
      if (prev) {
        const done = s.cards.find(
          (c) => prev.get(c.id) === 'open' && ['approved', 'sent', 'escalated', 'dismissed'].includes(c.status),
        )
        if (done) setJustDecided(done)
      }
      lastStatus.current = new Map(s.cards.map((c) => [c.id, c.status]))
    } catch {
      setError(true)
    }
  }, [])

  useEffect(() => {
    load()
    const poll = window.setInterval(load, POLL_MS)
    const tick = window.setInterval(() => setNowMs(Date.now() + offset.current), 15000)
    const nav = () => setPath(window.location.pathname)
    window.addEventListener('popstate', nav)
    return () => { clearInterval(poll); clearInterval(tick); window.removeEventListener('popstate', nav) }
  }, [load])

  const openDrawer = useCallback((card: Card, tab: 'evidence' | 'trail') => setDrawer({ card, tab }), [])

  if (!state) {
    return (
      <div className="grid h-full place-items-center text-ink-3">{error ? 'Cannot reach the server.' : 'Loading…'}</div>
    )
  }
  const clock = nowMs

  const single = path.match(/^\/d\/(.+)$/)
  if (single) {
    const id = decodeURIComponent(single[1])
    const card = state.cards.find((c) => c.id === id) ?? (offer?.card.id === id ? offer.card : undefined)
    return (
      <div className="min-h-full bg-white">
        <main className="mx-auto max-w-xl space-y-4 px-4 py-5">
          <div className="flex items-center justify-between gap-3">
            <a href="/" className="text-sm font-semibold text-ok hover:underline">← Inbox</a>
            <AlertsButton />
          </div>
          {card ? (
            <>
              {card.status !== 'open' && !offer && (
                <p className="rounded-lg bg-panel px-3 py-2 text-sm font-semibold text-ink-2">
                  Already {card.status === 'escalated' ? 'escalated' : card.status}.
                </p>
              )}
              <DecisionCard
                card={card}
                nowMs={clock}
                direct
                offer={offer}
                onOffer={setOffer}
                onChanged={load}
                onDrawer={openDrawer}
                ringing={ringing && card.status === 'open'}
                onRingingDone={stopRinging}
              />
            </>
          ) : (
            <p className="text-ink-2">This decision does not exist (any more).</p>
          )}
        </main>
        <EvidenceDrawer view={drawer} onClose={() => setDrawer(null)} />
      </div>
    )
  }

  return (
    <div className="flex h-full flex-col bg-white">
      <StatusStrip
        state={state}
        nowMs={clock}
        actions={<><Routines state={state} onChanged={load} request={automate} /><AlertsButton /></>}
      />
      <div className="grid min-h-0 flex-1 lg:grid-cols-[3fr_2fr]">
        <section className="relative hidden min-h-0 flex-col border-r border-line lg:flex">
          <div className="relative min-h-0 flex-1">
            <SupplyMap
              state={state}
              hoverRoutes={hoverRoutes}
              selection={selection}
              onSelect={setSelection}
              pulseNode={pulseNode}
            />
          </div>
          <Legend />
        </section>
        <aside className="min-h-0 overflow-y-auto bg-white px-4 py-5 lg:px-6">
          <Rail
            state={state}
            nowMs={clock}
            selection={selection}
            onClear={() => setSelection({})}
            fresh={fresh}
            offer={offer}
            onOffer={setOffer}
            onChanged={load}
            onHover={setHoverRoutes}
            onDrawer={openDrawer}
          />
        </aside>
      </div>
      {toast && (
        <div className="toast-in fixed left-1/2 top-24 z-50 -translate-x-1/2 rounded-xl border border-line bg-white px-5 py-3 text-[15px] font-semibold shadow-lg">
          <span className="mr-2 inline-block h-2.5 w-2.5 animate-pulse rounded-full bg-ok" />
          {toast}
        </div>
      )}
      <EvidenceDrawer view={drawer} onClose={() => setDrawer(null)} />
      {justDecided && (
        <AutomateOffer
          card={justDecided}
          onYes={() => { setAutomate({ cardId: justDecided.id, k: Date.now() }); setJustDecided(null) }}
          onNo={() => setJustDecided(null)}
        />
      )}
    </div>
  )
}

const DONE_WORD: Record<string, string> = { approved: 'Approved', sent: 'Sent', escalated: 'Escalated', dismissed: 'Dismissed' }

function AutomateOffer({ card, onYes, onNo }: { card: Card; onYes: () => void; onNo: () => void }) {
  return (
    <div className="toast-in fixed bottom-4 left-1/2 z-50 w-[min(640px,calc(100vw-32px))] -translate-x-1/2 rounded-2xl border border-line bg-white p-4 shadow-xl">
      <div className="text-sm font-semibold text-ok">{DONE_WORD[card.status] ?? 'Done'}: {card.headline}</div>
      <div className="mt-1 text-[17px] font-bold leading-snug">Handle cards like this automatically next time?</div>
      <div className="mt-1 text-[15px] text-ink-2">An agent writes a small routine from your decision and shows you a test run first. Anything that costs money still comes to you.</div>
      <div className="mt-3 flex gap-2">
        <button onClick={onYes} className="cursor-pointer rounded-lg bg-ok px-4 py-2 text-[15px] font-semibold text-white hover:bg-[#1859b8]">Write a routine</button>
        <button onClick={onNo} className="cursor-pointer rounded-lg px-4 py-2 text-[15px] font-semibold text-ink-2 hover:bg-panel">Not now</button>
      </div>
    </div>
  )
}

function Legend() {
  const sw = (c: string, label: string) => (
    <span className="inline-flex items-center gap-1.5"><span className="h-2.5 w-2.5 rounded-full" style={{ background: c }} />{label}</span>
  )
  const line = (dash: boolean, label: string) => (
    <span className="inline-flex items-center gap-1.5">
      <svg width="26" height="6"><line x1="1" y1="3" x2="25" y2="3" stroke="#475569" strokeWidth="2.5" strokeDasharray={dash ? '6 4' : undefined} strokeLinecap="round" /></svg>
      {label}
    </span>
  )
  return (
    <div className="flex flex-wrap items-center gap-x-5 gap-y-1 border-t border-line px-5 py-3 text-sm text-ink-2">
      {line(false, 'Air / truck')}
      {line(true, 'Sea')}
      <span className="h-4 w-px bg-line" />
      {sw(COLORS.blue, 'On track')}
      {sw(COLORS.amber, 'At risk')}
      {sw(COLORS.red, 'Stops a line')}
      {sw(COLORS.grey, 'Silent')}
    </div>
  )
}
import { Check, ChevronRight, FileSearch, Phone, Workflow } from 'lucide-react'
import { useState } from 'react'
import { Button } from '@/components/ui/button'
import { VoiceCall } from '@/components/VoiceCall'
import { COLORS, fmtDay, fmtNum, fmtTime, post, until, type Card } from '@/lib/api'
import { cn } from '@/lib/utils'

export interface Offer { cardId: string; type: string; card: Card }

interface Props {
  card: Card
  nowMs: number
  isNew?: boolean
  /** Opened from the deep link (/d/<id>): whoever it is routed to can act on it here. */
  direct?: boolean
  offer?: Offer | null
  onOffer: (o: Offer | null) => void
  onChanged: () => void
  onHover?: (routes: string[]) => void
  onDrawer: (card: Card, tab: 'evidence' | 'trail') => void
  ringing?: boolean
  onRingingDone?: () => void
}

// A person's first name; a role ('Head of Procurement', 'DC site lead') stays whole.
const first = (s?: string) => (!s ? '' : /\s[a-z]/.test(s) ? s : (s.split(' ').find((w) => !w.endsWith('.')) ?? s))

export function DecisionCard({
  card, nowMs, isNew, direct, offer, onOffer, onChanged, onHover, onDrawer, ringing, onRingingDone,
}: Props) {
  const [sel, setSel] = useState(0)
  const [mode, setMode] = useState<'idle' | 'edit' | 'escalate'>('idle')
  const [text, setText] = useState('')
  const [note, setNote] = useState('')
  const [busy, setBusy] = useState(false)
  const color = COLORS[card.level]
  const opt = card.options[sel]
  const due = until(card.deadline, nowMs)
  const other = card.routed_to_other || card.status === 'escalated'
  const who = first(card.approver) || 'the approver'
  const decided = !!offer && offer.cardId === card.id

  async function act(fn: () => Promise<unknown>) {
    setBusy(true)
    try { await fn() } finally { setBusy(false) }
  }
  const approve = () =>
    act(async () => {
      const r = await post<{ offer_trust: string | null }>(`/api/cards/${card.id}/approve`, {
        option: sel, text: mode === 'edit' ? text : undefined,
      })
      if (r.offer_trust) onOffer({ cardId: card.id, type: r.offer_trust, card })
      setMode('idle')
      onChanged()
    })
  const escalate = () =>
    act(async () => { await post(`/api/cards/${card.id}/escalate`, { note }); setMode('idle'); onChanged() })
  const dismiss = () => act(async () => { await post(`/api/cards/${card.id}/dismiss`); onChanged() })
  const trust = (m: 'allow_always' | 'ask') =>
    act(async () => { await post('/api/trust', { action_type: offer!.type, mode: m }); onOffer(null); onChanged() })

  return (
    <article
      onMouseEnter={() => onHover?.(card.routes)}
      onMouseLeave={() => onHover?.([])}
      className={cn('relative rounded-2xl border border-line bg-white p-5 pl-6', isNew && 'slide-in', other && 'bg-panel')}
    >
      <span className="absolute inset-y-0 left-0 w-1.5 rounded-l-2xl" style={{ background: color }} />

      <div className="flex flex-wrap items-center gap-x-2 text-sm text-ink-3">
        <span className="font-semibold text-ink-2">{card.supplier_name || card.part || 'Soony'}</span>
        {card.supplier_name && card.part && <span>· {card.part}</span>}
      </div>

      <h2 className="mt-1.5 text-[21px] font-bold leading-snug">{card.headline}</h2>

      <div className="mt-4 flex flex-wrap items-end gap-x-8 gap-y-2">
        {card.number != null && card.number > 0 && (
          <div>
            <div className="text-[40px] font-extrabold leading-none tabular-nums" style={{ color }}>{fmtNum(card.number)}</div>
            <div className="mt-1 text-sm font-medium text-ink-3">{card.number_label}</div>
          </div>
        )}
        {card.deadline && (
          <div>
            <div className={cn('text-[28px] font-extrabold leading-none tabular-nums', due?.urgent && 'text-stop')}>
              {fmtDay(card.deadline)} {fmtTime(card.deadline)}
            </div>
            <div className="mt-1 text-sm font-medium text-ink-3">decide by{due ? ` · ${due.text}` : ''}</div>
          </div>
        )}
      </div>

      {other && (
        <div className="mt-4 flex items-start gap-2 rounded-lg bg-white px-3 py-2 text-sm text-ink-2 ring-1 ring-line">
          <Phone size={16} className="mt-0.5 shrink-0 text-ink-3" />
          <div>
            <span className="font-semibold text-ink">
              {card.status === 'escalated'
                ? `Waiting for ${who}`
                : `With ${who}${card.called_at ? ` · called ${fmtTime(card.called_at)}` : ''}`}
            </span>
            {card.reason && <div>{card.reason}</div>}
          </div>
        </div>
      )}

      {(!other || direct) && !decided && opt && (
        <>
          <div className="mt-4 rounded-xl border-2 p-4" style={{ borderColor: `${color}55`, background: `${color}0d` }}>
            <div className="text-xs font-bold uppercase tracking-wide" style={{ color }}>
              {sel === 0 ? 'Recommended' : 'Option'}
            </div>
            <div className="mt-1 text-[17px] font-bold leading-snug">{opt.action}</div>
            <div className="mt-1 text-[15px] text-ink-2">{[opt.cost, opt.effect].filter(Boolean).join(' · ')}</div>
          </div>

          {card.options.length > 1 && (
            <ul className="mt-2 space-y-1">
              {card.options.map((o, i) =>
                i === sel ? null : (
                  <li key={i}>
                    <button
                      onClick={() => { setSel(i); setMode('idle') }}
                      className="flex w-full cursor-pointer items-center gap-2 rounded-lg px-3 py-2 text-left text-[15px] text-ink-2 hover:bg-panel"
                    >
                      <ChevronRight size={16} className="shrink-0 text-ink-3" />
                      <span className="font-medium">{o.action}</span>
                      <span className="ml-auto shrink-0 text-sm text-ink-3">{o.cost}</span>
                    </button>
                  </li>
                ),
              )}
            </ul>
          )}

          {mode === 'edit' && (
            <textarea
              value={text}
              onChange={(e) => setText(e.target.value)}
              rows={5}
              className="mt-3 w-full rounded-lg border border-line p-3 text-[15px] focus:outline-2 focus:outline-ok"
              aria-label="Edit draft"
            />
          )}
          {mode === 'escalate' && (
            <div className="mt-3 rounded-lg border border-line p-3">
              <div className="text-xs font-semibold uppercase tracking-wide text-ink-3">Brief for {who}</div>
              <p className="mt-1 text-[15px] text-ink-2">{card.escalation_brief}</p>
              <input
                value={note}
                onChange={(e) => setNote(e.target.value)}
                placeholder="Add one line (optional)"
                className="mt-3 h-10 w-full rounded-lg border border-line px-3 text-[15px] focus:outline-2 focus:outline-ok"
              />
              <div className="mt-3 flex gap-2">
                <Button size="sm" disabled={busy} onClick={escalate}>Send to {who}</Button>
                <Button size="sm" variant="ghost" onClick={() => setMode('idle')}>Cancel</Button>
              </div>
            </div>
          )}

          <div className="mt-4 flex flex-wrap gap-2">
            <Button disabled={busy} onClick={approve}>
              <Check size={18} /> {mode === 'edit' ? 'Approve edited' : 'Approve'}
            </Button>
            <Button
              variant="outline"
              disabled={!opt.draft && mode !== 'edit'}
              title={opt.draft ? undefined : 'This option has no draft to edit'}
              onClick={() => { setText(opt.draft ?? ''); setMode(mode === 'edit' ? 'idle' : 'edit') }}
            >
              Edit
            </Button>
            <Button variant="outline" onClick={() => setMode(mode === 'escalate' ? 'idle' : 'escalate')}>Escalate</Button>
            <Button variant="ghost" disabled={busy} onClick={dismiss}>Dismiss</Button>
          </div>
        </>
      )}

      {card.ui?.reply && (
        <div className="mt-4 rounded-xl border-2 border-ok/30 bg-ok/5 p-4">
          <div className="text-xs font-bold uppercase tracking-wide text-ok">
            Reply from {card.ui.reply_from || 'supplier'}
            {card.ui.reply_at ? ` · ${fmtDay(card.ui.reply_at)} ${fmtTime(card.ui.reply_at)}` : ''}
          </div>
          <p className="mt-1 text-[15px] font-medium leading-snug">{card.ui.reply}</p>
          {card.ui.reply_text && (
            <details className="mt-2">
              <summary className="cursor-pointer text-sm text-ink-3">Original email</summary>
              <pre className="mt-1 whitespace-pre-wrap break-words font-sans text-sm text-ink-2">{card.ui.reply_text}</pre>
            </details>
          )}
        </div>
      )}

      {!decided && (
        <VoiceCall card={card} onChanged={onChanged} ringing={ringing} onRingingDone={onRingingDone} />
      )}

      {decided && offer && (
        <div className="mt-4 rounded-xl border-2 border-ok/40 bg-ok/5 p-4">
          <div className="flex items-center gap-2 text-[15px] font-bold text-ok"><Check size={18} /> Approved</div>
          <p className="mt-2 text-[17px] font-semibold leading-snug">
            Send routine ETA chasers like this one automatically from now on?
          </p>
          <p className="mt-1 text-[15px] text-ink-2">You'll still approve anything that costs money.</p>
          <div className="mt-3 flex gap-2">
            <Button disabled={busy} onClick={() => trust('allow_always')}>Allow always</Button>
            <Button variant="outline" disabled={busy} onClick={() => trust('ask')}>Ask me each time</Button>
          </div>
        </div>
      )}

      <div className="mt-4 flex gap-5 border-t border-line pt-3 text-sm font-semibold text-ink-2">
        <button className="inline-flex cursor-pointer items-center gap-1.5 hover:text-ink" onClick={() => onDrawer(card, 'evidence')}>
          <FileSearch size={16} /> Evidence
        </button>
        <button className="inline-flex cursor-pointer items-center gap-1.5 hover:text-ink" onClick={() => onDrawer(card, 'trail')}>
          <Workflow size={16} /> Agent trail
        </button>
      </div>
    </article>
  )
}
export type Level = 'red' | 'amber' | 'grey' | 'blue'

export interface Option {
  index: number
  action?: string
  cost?: string
  effect?: string
  recommended: boolean
  draft?: string
  to?: string
  channel?: string
  routine_type?: string | null
}
export interface Evidence {
  source?: string
  value?: string | number
  doc?: string
  page?: number
  quote?: string
  translation?: string
  language?: string
  unit?: string
}
export interface TrailStep { agent?: string; at?: string; text?: string }

export interface Card {
  id: string
  kind?: string
  part?: string
  headline: string
  summary?: string
  number: number | null
  number_label: string
  edition?: string
  cell_hours_lost?: number
  slack_hours?: number
  deadline?: string
  runs_dry?: string | null
  severity?: string
  level: Level
  status: string
  approver?: string
  routed_to_other: boolean
  reason?: string
  called_at?: string
  options: Option[]
  evidence: Evidence[]
  trail: TrailStep[]
  supplier_id?: string
  supplier_name?: string
  shipment?: string
  routes: string[]
  ui: {
    status?: string; at?: string; note?: string
    // Supplier reply tied back by the alert agent (replies.py)
    reply?: string; reply_from?: string; reply_at?: string; reply_text?: string
  }
  escalation_brief: string
}

export interface MapNode { id: string; kind: 'supplier' | 'port' | 'dc' | 'site'; name: string; lat: number; lon: number; country?: string }
export interface Leg { id: string; origin: string; destination: string; mode: string; via?: string; path: [number, number][] | null }
export interface Shipment {
  id: string; route_id: string; mode: string; supplier_id: string; status: string
  eta?: string; etd?: string; progress: number; departed: boolean; silent: boolean; silent_hours?: number
  level: Level; note?: string
}
export interface StripItem {
  edition: string; label: string; level: Level; status: string
  copies_at_risk: number; slack_hours: number | null
  breaks_first: { text?: string; deadline?: string; stops_at?: string | null; card: string } | null
}
export interface EventItem { id: string; at: string; path?: string; file?: string; node?: string }
export interface ActivityItem { at?: string; text: string; kind: string; detail?: string; card?: string }

export interface State {
  now: string
  viewer: string
  portal_found: boolean
  map: { nodes: MapNode[]; legs: Leg[]; version: string }
  route_level: Record<string, Level>
  badges: Record<string, number>
  shipments: Shipment[]
  strip: StripItem[]
  cards: Card[]
  inbox_ids: string[]
  calm: boolean
  events: EventItem[]
  activity: ActivityItem[]
  last_drop_at: string | null
  last_check_at: string | null
  read_since_6: number
  trust: Record<string, string>
}

export async function fetchState(): Promise<State> {
  const r = await fetch('/api/state')
  if (!r.ok) throw new Error(`state ${r.status}`)
  return r.json()
}

export async function post<T = unknown>(url: string, body: unknown = {}): Promise<T> {
  const r = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) })
  if (!r.ok) throw new Error(`${url} ${r.status}`)
  return r.json()
}

export const COLORS: Record<Level, string> = {
  blue: '#1d6fe0',
  amber: '#d97706',
  red: '#dc2626',
  grey: '#7b8494',
}
export const LEVEL_RANK: Record<Level, number> = { red: 3, amber: 2, grey: 1, blue: 0 }

const TZ = 'Europe/Berlin'
export const fmtTime = (iso?: string | null) =>
  iso ? new Intl.DateTimeFormat('en-GB', { hour: '2-digit', minute: '2-digit', timeZone: TZ }).format(new Date(iso)) : ''
export const fmtDay = (iso?: string | null) =>
  iso ? new Intl.DateTimeFormat('en-GB', { weekday: 'short', timeZone: TZ }).format(new Date(iso)) : ''
export const fmtNum = (n: number | null | undefined) => (n == null ? '–' : Math.round(n).toLocaleString('en-GB'))

export function ago(iso: string | null | undefined, nowMs: number): string {
  if (!iso) return 'never'
  const min = Math.max(0, Math.round((nowMs - new Date(iso).getTime()) / 60000))
  if (min < 1) return 'just now'
  if (min < 60) return `${min} min ago`
  const h = Math.floor(min / 60)
  return h < 48 ? `${h} h ago` : `${Math.floor(h / 24)} days ago`
}

export function until(iso: string | undefined, nowMs: number): { text: string; urgent: boolean } | null {
  if (!iso) return null
  const min = Math.round((new Date(iso).getTime() - nowMs) / 60000)
  if (min <= 0) return { text: 'now', urgent: true }
  const text = min < 60 ? `${min} min` : `${Math.floor(min / 60)} h ${min % 60 ? `${min % 60} min` : ''}`.trim()
  return { text: `in ${text}`, urgent: min < 180 }
}
